import json
from pathlib import Path

from mock_api import TRACE, search
from timezone_defaults import MISSING_TZ_POLICY
from window_projection import parse_bound, utc_pair


def _normalization(window):
    start_utc, end_utc = utc_pair(window)
    return {
        "start_utc": start_utc.isoformat(),
        "end_utc": end_utc.isoformat(),
        "default_timezone": "UTC",
        "default_timezone_policy": MISSING_TZ_POLICY,
    }


def _error(param, message, payload, normalized=None):
    result = {
        "param": param,
        "error": message,
        "payload": payload,
    }
    if normalized is not None:
        result["normalized"] = normalized
    return result


def _fall_back_overlap(window):
    """Return whether this is an ambiguous, backwards wall-clock DST range."""
    start = window["start"]
    end = window["end"]
    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    return (
        start.date() == end.date()
        and start.hour == end.hour
        and start.utcoffset() != end.utcoffset()
        and end_local < start_local
    )


def validate_range(payload):
    errors = []
    if not isinstance(payload, dict):
        return [_error("query", "must be an object", payload)]
    if "start_date" not in payload:
        errors.append(_error("start_date", "is required", payload))
        return errors

    parsed = {}
    for param in ("start_date", "end_date"):
        if param not in payload:
            continue
        try:
            parsed[param] = parse_bound(payload[param])
        except (TypeError, ValueError):
            errors.append(_error(param, "must be a valid ISO 8601 datetime", payload))

    if errors or "end_date" not in payload:
        return errors

    window = {"start": parsed["start_date"], "end": parsed["end_date"], "payload": payload}
    normalized = _normalization(window)
    start_utc, end_utc = utc_pair(window)
    if end_utc < start_utc:
        errors.append(_error(
            "date_range",
            "end_date must not be before start_date after UTC normalization",
            payload,
            normalized,
        ))
    if _fall_back_overlap(window):
        errors.append(_error(
            "date_range",
            "fall-back DST range has an earlier end wall-clock time with different offsets",
            payload,
            normalized,
        ))
    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

